// === Tab: mySketch ===
var t = 0;
var stars = [];
var mountainLayers = [];
var mountainsBuffer;

var AURORA_PALETTE = [
  "#69e9d9",
  "#07aa75",
  "#7942bb",
  "#004faa",
  "#2a2a50",
];

function setup() {
  createCanvas(windowWidth, windowHeight);
  pixelDensity(1);
  noiseDetail(5, 0.55);
  initStars();
  initMountainLayers();
  renderMountainsBuffer();
}

function draw() {
  blendMode(BLEND);
  drawSkyGradient();
  drawStars();

  blendMode(SCREEN);

  drawAuroraLayer({
    baseY: height * 0.44,
    amp: 62,
    shiftAmp: 30,
    minHeight: 150,
    maxHeight: 560,
    step: 2,
    boxWidth: 5,
    noiseScale: 0.0045,
    colorNoiseScale: 0.03,
    peakNoiseScale: 6.4,
    peakStrength: 1.45,
    tiltAmp: 34,
    speed: 0.004,
    alpha: 55,
  });

  drawAuroraLayer({
    baseY: height * 0.52,
    amp: 56,
    shiftAmp: 28,
    minHeight: 150,
    maxHeight: 620,
    step: 2,
    boxWidth: 6,
    noiseScale: 0.0075,
    colorNoiseScale: 0.045,
    peakNoiseScale: 5.8,
    peakStrength: 1.55,
    tiltAmp: 38,
    speed: 0.0055,
    alpha: 85,
  });

  drawAuroraLayer({
    baseY: height * 0.6,
    amp: 42,
    shiftAmp: 24,
    minHeight: 180,
    maxHeight: 720,
    step: 2,
    boxWidth: 8,
    noiseScale: 0.011,
    colorNoiseScale: 0.06,
    peakNoiseScale: 5.2,
    peakStrength: 1.75,
    tiltAmp: 46,
    speed: 0.007,
    alpha: 125,
  });

  blendMode(BLEND);
  drawMountains();
  t += 1;
}

function drawAuroraLayer(opts) {
  const {
    baseY,
    amp,
    shiftAmp,
    minHeight,
    maxHeight,
    step,
    boxWidth,
    noiseScale,
    colorNoiseScale,
    peakNoiseScale,
    peakStrength,
    tiltAmp,
    speed,
    alpha,
  } = opts;

  const nt = t * speed;

  for (x = -50; x <= width + 50; x += step) {
    const nx = x * noiseScale;

    // Main continuous ribbon/spine
    const spineWave = map(noise(nx, nt), 0, 1, -amp, amp);

    // Extra smooth vertical drift so each column breathes up/down
    const localShift = map(
      noise(nx * 1.8 + 500, nt * 0.55 + 90),
      0,
      1,
      -shiftAmp,
      shiftAmp
    );

    const spineY = baseY + spineWave + localShift;

    // Height with explicit min/max
    let hNoise = noise(nx * 1.6 + 40, nt * 0.8 + 100);
    hNoise = pow(hNoise, 1.6);
    const baseHeight = lerp(minHeight, maxHeight, hNoise);

    const peakNoise = noise(nx * peakNoiseScale + 4000, nt * 2.2 + 9000);
    const peak = smoothen(0.35, 0.92, peakNoise);
    const rayHeight = baseHeight * lerp(0.68, peakStrength, peak);

    // Soft flowing intensity
    let intensity = noise(nx * 3.2 + 200, nt * 1.4);
    intensity = smoothen(0.28, 0.95, intensity);
    intensity *= lerp(0.28, 1.35, peak);

    const brokenStripe = smoothen(
      0.18,
      0.82,
      noise(nx * peakNoiseScale * 1.7 + 12000, nt * 2.8 + 16000)
    );
    intensity *= brokenStripe;

    // Larger color noise scale = more frequent color variation
    const colorNoise = noise(x * colorNoiseScale, nt * 1.8 + 700);
    const col = paletteColor(colorNoise, AURORA_PALETTE);

    if (intensity <= 0.01) continue;

    drawGradientStrip({
      x,
      y: spineY - rayHeight,
      w: boxWidth,
      h: rayHeight,
      col,
      alpha: alpha * intensity,
      midPoint: 0.35 + noise(nx * 2.2 + 900, nt * 1.3) * 0.24,
      tilt: map(noise(nx * 5.4 + 20000, nt * 1.7 + 30000), 0, 1, -tiltAmp, tiltAmp),
    });
  }
}

function paletteColor(v, palette) {
  const index = floor(constrain(v, 0, 0.999999) * palette.length);
  return color(palette[index]);
}

function drawSkyGradient() {
  const ctx = drawingContext;
  const grad = ctx.createLinearGradient(0, height, 0, 0);

  grad.addColorStop(0, "#311326");
  grad.addColorStop(0.2, "#a43a4d");
  grad.addColorStop(0.52, "#12395d");
  grad.addColorStop(0.76, "#06182e");
  grad.addColorStop(1, "#00030a");

  ctx.save();
  ctx.globalCompositeOperation = "source-over";
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();
}

function initStars() {
  stars = [];

  for (i = 0; i < 340; i++) {
    const yBias = random() * random() * random();

    stars.push({
      x: random(),
      y: yBias * 0.8,
      size: random(0.6, 2.3),
      alpha: random(55, 185),
    });
  }
}

function drawStars() {
  noStroke();

  for (const star of stars) {
    const pulse = smoothen(
      0.15,
      0.95,
      noise(star.x * 18 + 1000, star.y * 18 + 2000, t * 0.018)
    );
    const twinkle = 0.55 + pulse * 0.9;

    fill(255, star.alpha * twinkle);
    circle(star.x * width, star.y * height, star.size * twinkle);
  }
}

function initMountainLayers() {
  mountainLayers = [];

  const layerCount = 5;
  const horizonY = height * 0.74;

  for (i = 0; i < layerCount; i++) {
    const depth = i / (layerCount - 1);
    const baseY = lerp(horizonY + height * 0.02, height + height * 0.08, depth);
    const peakHeight = lerp(height * 0.28, height * 0.46, depth);
    const segments = floor(lerp(8, 15, depth));
    const opacity = lerp(255, 210, depth);
    const poly = generateMountainRidge(baseY, peakHeight, segments, depth);

    mountainLayers.push({
      poly,
      base: color(lerpColor(color("#030814"), color("#15314a"), depth)),
      opacity,
      strokeAlpha: lerp(40, 115, depth),
    });
  }
}

function renderMountainsBuffer() {
  mountainsBuffer = createGraphics(width, height);
  mountainsBuffer.pixelDensity(1);
  mountainsBuffer.clear();
  mountainsBuffer.blendMode(BLEND);

  for (const layer of mountainLayers) {
    drawMountainSilhouetteLayer(mountainsBuffer, layer);
  }
}

function generateMountainRidge(baseY, peakHeight, segments, depth) {
  const pts = [{ x: -80, y: baseY }];
  const xStep = (width + 160) / segments;

  for (i = 0; i <= segments; i++) {
    const x = -80 + i * xStep;
    const xNorm = constrain(x / width, 0, 1);
    const sideHeight = pow(abs(xNorm - 0.5) * 2, 1.35);
    const heightFactor = lerp(0.42, 1.28, sideHeight);
    const n = noise(i * 0.72 + depth * 30, depth * 90);
    const jag = random(-height * 0.035, height * 0.035);
    const y = baseY - peakHeight * heightFactor * lerp(0.55, 1.15, n) + jag;

    pts.push({ x, y });
  }

  pts.push({ x: width + 80, y: baseY + height * 0.12 });
  pts.push({ x: width + 80, y: height + 80 });
  pts.push({ x: -80, y: height + 80 });

  return pts;
}

function drawMountains() {
  image(mountainsBuffer, 0, 0);
}

function drawMountainSilhouetteLayer(pg, layer) {
  const bounds = polygonBounds(layer.poly);

  clipPolygon(pg, layer.poly, () => {
    const base = color(layer.base);
    base.setAlpha(layer.opacity);
    pg.fill(base);
    pg.noStroke();
    pg.rect(bounds.minX, bounds.minY, bounds.maxX - bounds.minX, bounds.maxY - bounds.minY);
  });

  pg.noFill();
  pg.stroke(0, 10, 22, layer.strokeAlpha);
  pg.strokeWeight(1.6);
  drawPolyShape(pg, layer.poly);
}

function drawGradientStrip({ x, y, w, h, col, alpha, midPoint, tilt }) {
  var ctx = drawingContext;
  var grad = ctx.createLinearGradient(x - tilt * 0.35, y, x + tilt * 0.65, y + h);
  const bright = brighten(col, 1.35);
  const top = withAlpha(col, 0);
  const mid = withAlpha(bright, alpha);
  const bottom = withAlpha(shiftColor(col, 16), 0);

  grad.addColorStop(0, top);
  grad.addColorStop(constrain(midPoint - 0.24, 0, 1), withAlpha(bright, 0));
  grad.addColorStop(constrain(midPoint, 0, 1), mid);
  grad.addColorStop(constrain(midPoint + 0.32, 0, 1), withAlpha(bright, 0));
  grad.addColorStop(1, bottom);

  noStroke();
  ctx.fillStyle = grad;

  const wobble = map(noise(x * 0.02, y * 0.004, t * 0.008), 0, 1, -3, 3);
  ctx.fillRect(x + wobble, y, w, h);
}

function brighten(c, amount) {
  return color(
    min(red(c) * amount, 255),
    min(green(c) * amount, 255),
    min(blue(c) * amount, 255),
    alpha(c)
  );
}

function shiftColor(c, amount) {
  return color(
    constrain(red(c) + amount, 0, 255),
    constrain(green(c) + amount, 0, 255),
    constrain(blue(c) + amount, 0, 255),
    alpha(c)
  );
}

function withAlpha(c, a) {
  return `rgba(${red(c)}, ${green(c)}, ${blue(c)}, ${constrain(a, 0, 255) / 255})`;
}

function smoothen(edge0, edge1, x) {
  const v = constrain((x - edge0) / (edge1 - edge0), 0, 1);
  return v * v * (3 - 2 * v);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  initStars();
  initMountainLayers();
  renderMountainsBuffer();
}

function clipPolygon(pg, points, drawFn) {
  var ctx = pg.drawingContext;

  ctx.save();
  ctx.beginPath();
  ctx.moveTo(points[0].x, points[0].y);

  for (i = 1; i < points.length; i++) {
    ctx.lineTo(points[i].x, points[i].y);
  }

  ctx.closePath();
  ctx.clip();
  drawFn();
  ctx.restore();
}

function drawPolyShape(pg, points) {
  pg.beginShape();
  for (const p of points) pg.vertex(p.x, p.y);
  pg.endShape(CLOSE);
}

function polygonBounds(poly) {
  return {
    minX: min(poly.map((p) => p.x)),
    maxX: max(poly.map((p) => p.x)),
    minY: min(poly.map((p) => p.y)),
    maxY: max(poly.map((p) => p.y)),
  };
}
